4. Расширенная настройка для Cline
Добавьте MCP-сервер (Model Context Protocol)
Создайте graphify-mcp-server.js:

javascript
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { exec } from 'child_process';
import { promisify } from 'util';
const execAsync = promisify(exec);
const server = new Server({
  name: 'graphify-mcp',
  version: '1.0.0',
}, {
  capabilities: {
    tools: {}
  }
});
server.setRequestHandler('tools/list', async () => ({
  tools: [
    {
      name: 'graphify_affected',
      description: 'Найти все файлы, зависящие от указанного компонента/функции',
      inputSchema: {
        type: 'object',
        properties: {
          target: { type: 'string', description: 'Имя функции, компонента или переменной' },
          depth: { type: 'number', description: 'Глубина поиска (по умолчанию 2)' }
        }
      }
    },
    {
      name: 'graphify_query',
      description: 'Задать вопрос по архитектуре проекта',
      inputSchema: {
        type: 'object',
        properties: {
          question: { type: 'string', description: 'Вопрос на естественном языке' }
        }
      }
    }
  ]
}));
server.setRequestHandler('tools/call', async (request) => {
  const { name, arguments: args } = request.params;

  let command;
  if (name === 'graphify_affected') {
    command = graphify affected "${args.target}" depth ${args.depth2};
  } else if (name === 'graphify_query') {
    command = graphify query "${args.question}";
  }

  const { stdout, stderr } = await execAsync(command, { cwd: process.cwd() });
  return {
    content: [{ type: 'text', text: stdoutstderr }]
  };
});
const transport = new StdioServerTransport();
await server.connect(transport);

Подключите в Cline через настройки MCP-серверов.

5. Практический чек-лист для ежедневной работы
